<?php
/**
 * 语言接口
 */

class LangAction extends BaseAction{

	protected $service_lang = array();

	public function _initialize(){
		$langModel = D('Lang');
		$this->service_lang = $langModel->service_lang;
		if(in_array(ACTION_NAME,array('service','get','report','add','daoru'))){
			parent::_initialize();
		}
	}

	/**
	 * 获取系统支持的语言
	 */
	public function service(){
		$this->returnCode(0,$this->service_lang);
	}

	/**
	 * 获取语言
	 * group string 分组名称
	 * lang  string 需要获得的语言
	 * @return [json]
	 */
	public function get(){
		switch($_POST['from']){
			case 'deliver':
				$_POST['from'] = 1;
				break;
			case 'merchant':
				$_POST['from'] = 2;
				break;
			case 'storestaff':
				$_POST['from'] = 3;
				break;
			case 'app':
			case 'wxapp':
				$_POST['from'] = 4;
				break;
		}
		$field = C('config.system_lang') ? C('config.system_lang') : C('config.default_language');
		$from = $_POST['from'] ? $_POST['from'] : 4;//来源 1=配送员wap 2=商户wap 3=店员wap 4=用户端app小程序
		
		$cache_name = 'lang/app_get'.$from.$field;
		$output = S($cache_name);
		if(empty($output)){
			$where = array();
			$where['from'] = $from;//原生app/微信小程序
			$where['is_del'] = 0;
			$all_lang = M('Lang')->field('key,'.$field)->where($where)->order('add_time desc')->group('`key`')->select();

			$output = $all_lang ? array_column($all_lang, $field, 'key') : array();
			
			S($cache_name, $output, 86400);
		}
		
		if(!$output){
			$output = (object)array();
		}
		
		$this->returnCode(0,$output);
	}

	/**
	 * app端/小程序端找不到翻译提交词语接口
	 * 支持多个词语共同提交
	 */
	public function report(){
		$group_name = 'appapi';
		$module_name = $_POST['from'] ? $_POST['from'] : '';
		$action_name = $_POST['page'] ? $_POST['page'] : '';
		switch($_POST['from']){
			case 'deliver':
				$_POST['from'] = 1;
				break;
			case 'merchant':
				$_POST['from'] = 2;
				break;
			case 'storestaff':
				$_POST['from'] = 3;
				break;
			case 'app':
			case 'wxapp':
				$_POST['from'] = 4;
				break;
		}
		//引入繁体类
    	import("@.ORG.ZhConvert");
		
		$keywords = trim($_POST['keywords']);
		$from = $_POST['from'] ? $_POST['from'] : 4;//来源 1=配送员wap 2=商户wap 3=店员wap 4=用户端app小程序
		if(empty($keywords)) $this->returnCode(0,array());
		$data = array();
		if(is_array($keywords)){
			foreach ($keywords as $value) {
				$condition = array(
					'key' => $value,
					'from' => $_POST['from']
				);
				if(!M('Lang')->where($condition)->find()){
					$data[] = array(
						'key' => trim($value),
						'chinese' => trim($value),
						'from' => $from,
						'group_name' => $group_name,
						'module_name' => $module_name,
						'action_name' => $action_name,
						'add_time' => time()
					);
				}
			}
			if($data){
				M('Lang')->addAll($data);
			}
			$this->returnCode(0,$data);
		}else{
			$condition = array(
				'key' => $keywords,
				'from' => $_POST['from']
			);
			if(M('Lang')->where($condition)->find()){
				$this->returnCode(0,array());
			}
			$data[] = array(
				'key' => trim($keywords),
				'chinese' => trim($keywords),
				'english' => '',		//测试用
				'traditional' => ZhConvert::zh($keywords),
				'from' => $from,
				'group_name' => $group_name,
				'module_name' => $module_name,
				'action_name' => $action_name,
				'add_time' => time()
			);
			M('Lang')->addAll($data);
			$this->returnCode(0,$data);
		}
		
	}

	/**
	 * js获取语言
	 * @return [type] [description]
	 */
	public function js(){
		header('Content-type: text/javascript');  
		if(!C('config.open_multilingual')){
			exit('');
		}
		$fields = I('lang') ? I('lang') : 'chinese';
		$all_lang = M('Lang')->field('key,group_name,module_name,action_name,'.$fields)->where("`from`=0")->select();

		$lang = array();
        foreach ($all_lang as $key => $value) {
        	if(!$value[$fields]) $value[$fields] = "";
            $lang[$value['key']] = $value[$fields];
        }

        $jsoncode = json_encode($lang);
        if(IS_AJAX){
        	echo json_encode(array('key'=>md5($jsoncode),'lang'=>$jsoncode));
        	exit;
        }
        else{
        	echo "var md5langkey = '".md5($jsoncode)."';";
        	exit;
        }
	}

	/**
	 * js添加词语
	 */
	public function add(){
		$key = I('key');
		L_($key,'',true);
		exit;
	}

	/**
	 * 快捷建立视图
	 */
	public function fast_view(){
		set_time_limit(0);
		if(IS_POST){
			$table 	= trim(I('table'));
			$fields = trim(I('fields'));
			// $table = "merchant_store";
			// $fields = "store_id,name,adress";
			if(empty($table)){
				die("table empty!");
			}
			if(empty($fields)){
				die("fields empty!");
			}
			$model = M($table);
			$db_pk = $model->getPk();
			$db_fields = $model->getDbFields();
			$db_fields_type = $model->getFieldType()['_type'];
			if(!$db_fields){
				die('table not exist!');
			}
			$fields_arr = explode(',', $fields);
			if(!in_array($db_pk, $fields_arr)){
				die('pk empty!');
			}
			foreach ($fields_arr as $value) {
				if(!in_array($value, $db_fields))
				{
					die('fields error!');
				}
			}

			$db = M();
			foreach ($this->service_lang as $key => $value) {
				$sql = "DROP TABLE IF EXISTS `pigcms_".$table."_".$value['val']."` ; ";
				$db->execute($sql);
				$sql = "CREATE TABLE IF NOT EXISTS `pigcms_".$table."_".$value['val']."` (";
				$temp = array();
				foreach ($fields_arr as $field) {
					$temp[] = "`".$field."_".$value['val']."` ".$db_fields_type[$field];	
				}	
				$sql .= implode(',', $temp)." , PRIMARY KEY (`".$db_pk."_".$value['val']."`) ) ENGINE=InnoDB  DEFAULT CHARSET=utf8;";
				// $sql = "select * from pigcms_config limit 1";
				$db->execute($sql);
				echo "<br/>";
				echo "pigcms_".$table."_".$value['val']." create success...";


				$sql = "CREATE OR REPLACE algorithm = MERGE ";
				$sql .= "view pigcms_".$table."_".$value['val']."_view as ( ";
				$sql .= "select a.*,b.*	from pigcms_".$table." as a inner join pigcms_".$table."_".$value['val']." as b on a.".$db_pk."=b.".$db_pk."_".$value['val'].")";
				$db->execute($sql);
				echo "<br/>";
				echo "pigcms_".$table."_".$value['val']."_view create success...";
			}
		}
	    echo "<form action=".U('fast_view')." method='POST'>";
	    echo "表名：<input type='text' name='table' value='' /><br/>";
	    echo "字段名（逗号隔开）：<input type='text' name='fields' value='' /><br/>";	
	    echo "<input type='submit' value='提交' />";
	    echo "</form>";	

	}

	/**
	 * 批量修改所有数据表 表字段的编码
	 */
	public function update_all_tables(){
		set_time_limit(0);
		
		$db = M();
		//修改数据库编码
		//$db->execute("alter database ".C("DB_NAME")." character set utf8mb4");

		$all_tables = $db->query("show tables");
		$allow_field_type = ['TEXT','CHAR'];
		$num_pattern = "/\(([\d]+)\)/";
		ob_end_clean();
		ob_implicit_flush(true); 
		$i = 1;
		$limit = 50;
		$stop = I('stop') ? I('stop') : 0;
		echo "<html><body>";
		foreach ($all_tables as $key => $value) {
			if($stop !== 0 && intval($key) < intval($stop)) continue;
			if($i == $limit){
				$stop = $key;
				break;
			}
			$all_fields = $db->query("describe `".$value['Tables_in_'.C("DB_NAME")]."`");
			if($all_fields){
				foreach ($all_fields as $fields) {
					$fields['Type'] = strtoupper($fields['Type']);
					if(strpos($fields['Type'], $allow_field_type[0]) !== false || strpos($fields['Type'], $allow_field_type[1]) !== false){
						preg_match($num_pattern, $fields['Type'], $matches);
						if(isset($matches[1])){
							$mch = trim($matches[1]);
							$fields['Type'] = preg_replace($num_pattern, '('.$mch.')', $fields['Type']);
						}
						
						$sql = "ALTER TABLE  `".$value['Tables_in_'.C("DB_NAME")]."` CHANGE  `".$fields['Field']."`  `".$fields['Field']."` ".$fields['Type']." CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci not null";
						$db->execute($sql);
					}
				}
			}
			$db->execute("ALTER TABLE  `".$value['Tables_in_'.C("DB_NAME")]."` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");
			$db->execute("REPAIR TABLE  `".$value['Tables_in_'.C("DB_NAME")]."`");
			$db->execute("OPTIMIZE TABLE  `".$value['Tables_in_'.C("DB_NAME")]."`");
			echo $value['Tables_in_'.C("DB_NAME")]." has complete!<br/>";
			$i++;
		}
		echo "</body></html>";
		if($i != $limit){
			echo "complete!!!";
			exit;
		}
		else{
			echo "<script type='text/javascript'>window.location.href='".U('update_all_tables',array('stop' => $stop))."';</script>";
			exit;
		}
	}

